 const at = "2026-10-28T10:00:00Z";
@@ -27,3 +28,34 @@ test("waste is recorded against a batch", () => {
   assert.equal(m.type, "waste");
   assert.equal(store.data.batches.find((b) => b.id === 6).qty, 12);
 });
+
+test("consume takes the batch that expires first (FEFO)", () => {
+  const store = fresh();
+  // Milk: lot HD-1022 (batch 4) expires before the newer lot HD-1026 (batch 3).
+  assert.deepEqual(consume(store, 2, 1, { at }), [{ batchId: 4, qty: 1 }]);
+  assert.deepEqual(consume(store, 2, 3, { at }), [
+    { batchId: 4, qty: 1 },
+    { batchId: 3, qty: 2 },
+  ]);
+});
+
+test("cooking bechamel uses the milk lot that expires first", () => {
+  const store = fresh();
+  const recipe = store.data.recipes.find((r) => r.name === "bechamel");
+  const milk = cook(store, recipe.id, recipe.portions, { at }).find((u) => u.itemId === 2);
+  assert.equal(store.data.batches.find((b) => b.id === milk.batches[0].batchId).lot, "HD-1022");
+});
+
+test("consumption order: no expiry last, then first received, then lower id", () => {
+  const store = fresh();
+  const base = { itemId: 2, qty: 1, location: "fridge" };
+  store.data.batches = [
+    { ...base, id: 901, lot: "none", receivedOn: "2026-10-01", expires: null },
+    { ...base, id: 903, lot: "tie-high-id", receivedOn: "2026-10-20", expires: "2026-11-05" },
+    { ...base, id: 902, lot: "tie-low-id", receivedOn: "2026-10-20", expires: "2026-11-05" },
+    { ...base, id: 904, lot: "later-received", receivedOn: "2026-10-21", expires: "2026-11-05" },
+    { ...base, id: 905, lot: "first-expiry", receivedOn: "2026-10-25", expires: "2026-11-01" },
+  ];
+  const used = consume(store, 2, 5, { at });
+  assert.deepEqual(used.map((u) => u.batchId), [905, 902, 903, 904, 901]);
+});
